const ALL: Row[] = [...RAW, ...RAW2, ...RAW3];

function norm(s: string): string {
  return s.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "");
}

function normalBalanceOf(code: string, cls: AccountClass): "debit" | "credit" {
  // Provisions / amortissements / dépréciations → crédit
  if (/^(28|29|39|49|59)/.test(code)) return "credit";
  if (/^56/.test(code)) return "credit"; // crédits de trésorerie
  if (/^19/.test(code)) return "credit";
  if (cls === 1) return /^(109|129)/.test(code) ? "debit" : "credit";
  if (cls === 2) return "debit";
  if (cls === 3) return "debit";
  if (cls === 4) {
    if (/^409/.test(code) || /^416/.test(code) || /^478/.test(code)) return "debit";
    if (/^419/.test(code) || /^479/.test(code)) return "credit";
    if (/^4[0]/.test(code)) return "credit";
    if (/^41/.test(code)) return "debit";
    if (/^42/.test(code)) return /^(421)/.test(code) ? "debit" : "credit";
    return "credit";
  }
  if (cls === 5) return "debit";
  if (cls === 6) return "debit";
  if (cls === 7) return "credit";
  if (cls === 8) return /^(8[13579])/.test(code) ? "debit" : "credit";
  if (cls === 9) return /^91/.test(code) ? "credit" : "debit";
  return "debit";
}

function buildAccounts(): Account[] {
  const codes = new Set(ALL.map((r) => r[0]));
  return ALL.map(([code, label, cls]) => {
    const hasChildren = ALL.some((r) => r[0].startsWith(code) && r[0].length > code.length);
    const parentCode = code.length > 1 ? code.slice(0, -1) : null;
    // si le parent direct n'existe pas (saut de niveau), on remonte
    let pc = parentCode;
    while (pc && !codes.has(pc)) pc = pc.slice(0, -1);
    const type: Account["type"] = code.length === 1 ? "class" : code.length === 2 ? "account" : "subaccount";
    return {
      code, label, classNumber: cls,
      parentCode: pc,
      type,
      normalBalance: normalBalanceOf(code, cls),
      postable: !hasChildren,
      depth: Math.min(code.length, 5),
      nature: cls <= 5 ? "bilan" : "gestion",
      keywords: norm(`${code} ${label}`),
    };
  });
}

